using System.Linq;

namespace TrueToneCap.App.Models;

/// <summary>
/// 框选工具条的唯一动作词表 —— 2026-10-26 起替代 HdrCaptureAction（D3D 预览窗）
/// 与 SelectionOverlay.ActionResult（XAML 兜底层）两套各自漂移的枚举。
/// SDR 侧原叫 Confirm 的那枚在这里统一叫 Save（行为相同：EncodeAndSaveAsync 落盘+剪贴板）。
/// </summary>
public enum MainToolbarAction { Cancel, Save, Copy, Annotate, Ocr, Translate, Qr }

/// <summary>主工具条上一枚按钮的完整声明：两个渲染器（D3D 烘字图集 / XAML 按钮）各取所需。</summary>
/// <param name="Glyph">D3D 烘字图集用的图标字形（"☑ 保存" 形态里的前半）；XAML 侧不用。</param>
/// <param name="IconPath">XAML PathIcon 的矢量几何（Data mini-language）；D3D 侧不用。</param>
/// <param name="Hint">悬停提示。两个入口共用同一句 —— 这正是 2026-10-26 二维码按钮
/// 只落 SDR 漏 HDR 那类事故的解药：文案只有一处可改。每句都必须是 LocaleManager 对照表的键，
/// 这样 SDR 的运行时扫描能翻英文，D3D 烘字（三路检测全盲的那扇窗）也从这一刻起有了静态可见的声明。</param>
public sealed record ToolbarButtonDef(
    MainToolbarAction Action,
    string Glyph,
    string Text,
    string Hint,
    string IconPath,
    bool Accent = false,
    double WidthDip = 140,
    float FontSizeDip = 28f);

/// <summary>标注工具条的一枚工具（目前只有 D3D 预览窗内联标注使用；SDR 兜底层的标注栏仍是 XAML）。</summary>
public sealed record ToolbarAnnoTool(string Glyph, string Text);

