    /// <summary>静置提示（未框选、未拖拽时居中显示；图集槽 35）。原 SDR 兜底层 HintText 用的也是这一句。</summary>
    public const string IdleHint = "单击 = 全屏  |  拖拽 = 框选  |  Esc = 取消";

    /// <summary>选区尺寸徽标文字（画在选区上方居中；与已删除的 SDR 兜底层 SizeLabel 同形）。</summary>
    public static string SizeBadgeText(int w, int h) => $"{w} × {h}";

    /// <summary>
    /// 估算一句提示在 <paramref name="fontPx"/> 字号下的像素宽（CJK/全角 ≈ 1em，其余 ≈ 0.6em，加 12px 余量）。
    /// 图集构建、CompositeUI 提示位、GDI 回退三处共用 —— 之前提示框写死 160 逻辑像素，
    /// 长提示（"标注选区（矩形/箭头/马赛克等）" 15 字）在 100% DPI 下必然裁边；逐钮提示上 GPU 后按最长句取宽。
    /// </summary>
    public static int EstimateTextWidthPx(string s, float fontPx)
    {
        double w = 0;
        foreach (var ch in s)
            w += ch >= 0x2E80 ? fontPx : fontPx * 0.6;
        return (int)Math.Ceiling(w) + 12;
    }

    /// <summary>主工具条悬停提示框的统一宽度（物理像素）：按最长一句估，下限 120。</summary>
    public static int MainHintWidthPx(float fontPx)
        => Math.Max(120, Main.Max(b => EstimateTextWidthPx(b.Hint, fontPx)));
}
